# Generated by test-lab — blind adversarial evaluation
"""
Blind evaluation checks for Node.js/CommonJS scripts.

Verifies batch runner scripts (*.cjs / *.js) against conventions:
- File presence and basic structure
- --dry-run / --help CLI flags
- JSONL output schema compliance
- CDP harness integration patterns
- Target command counts (text + voice)
- Error-handling boilerplate

Inputs: target directory path
Outputs: list[TestCheck] results
Failure modes: unreadable files (skipped)
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

from loguru import logger

_parent = str(Path(__file__).parent.parent)
if _parent not in sys.path:
    sys.path.insert(0, _parent)

from test_lab import TestCheck


# ---------------------------------------------------------------------------
# Checks
# ---------------------------------------------------------------------------

def run_checks(target_dir: Path) -> list[TestCheck]:
    """Run all Node.js best-practices checks against target directory."""
    checks: list[TestCheck] = []

    cjs_files = list(target_dir.rglob("*.cjs")) + list(target_dir.rglob("*.js"))
    # Exclude node_modules, dist, .git
    cjs_files = [
        f for f in cjs_files
        if not any(part in f.parts for part in ("node_modules", "dist", ".git", ".venv"))
    ]

    if not cjs_files:
        checks.append(TestCheck(
            name="node_files_exist",
            category="structure",
            passed=False,
            description="No .cjs/.js files found in target directory",
        ))
        return checks

    checks.append(TestCheck(
        name="node_files_exist",
        category="structure",
        passed=True,
        description=f"Found {len(cjs_files)} Node.js file(s)",
    ))

    # Run per-file checks
    for f in cjs_files:
        checks.extend(_check_node_file(f))

    return checks


def _check_node_file(f: Path) -> list[TestCheck]:
    """Check a single .cjs/.js file for best-practices patterns."""
    checks: list[TestCheck] = []

    try:
        content = f.read_text(encoding="utf-8")
    except Exception as e:
        logger.warning("Could not read {}: {}", f, e)
        return checks

    name = f.stem

    # ── 1. Shebang / strict mode ──────────────────────────────────────────
    has_strict = "'use strict'" in content or '"use strict"' in content
    checks.append(TestCheck(
        name=f"{name}:strict_mode",
        category="conventions",
        passed=has_strict,
        description=(
            f"{f.name}: uses 'use strict'" if has_strict
            else f"{f.name}: missing 'use strict' declaration"
        ),
    ))

    # ── 2. --dry-run flag ─────────────────────────────────────────────────
    has_dry_run = "--dry-run" in content
    checks.append(TestCheck(
        name=f"{name}:dry_run_flag",
        category="testing",
        passed=has_dry_run,
        description=(
            f"{f.name}: implements --dry-run flag" if has_dry_run
            else f"{f.name}: missing --dry-run flag (required for CI)"
        ),
    ))

    # ── 3. --help flag ────────────────────────────────────────────────────
    has_help = "--help" in content or "showHelp" in content or "show_help" in content
    checks.append(TestCheck(
        name=f"{name}:help_flag",
        category="conventions",
        passed=has_help,
        description=(
            f"{f.name}: implements --help flag" if has_help
            else f"{f.name}: missing --help flag"
        ),
    ))

    # ── 4. JSONL output schema ────────────────────────────────────────────
    jsonl_fields = ["command", "expected", "actual_queryspec", "scene_count",
                    "clarify_triggered", "errors"]
    missing_fields = [fld for fld in jsonl_fields if fld not in content]
    has_schema = len(missing_fields) == 0
    checks.append(TestCheck(
        name=f"{name}:jsonl_output_schema",
        category="correctness",
        passed=has_schema,
        description=(
            f"{f.name}: JSONL output schema complete" if has_schema
            else f"{f.name}: JSONL output missing fields: {missing_fields}"
        ),
    ))

    # ── 5. Screenshot capture ─────────────────────────────────────────────
    has_screenshot = "screenshot" in content.lower()
    checks.append(TestCheck(
        name=f"{name}:screenshot_capture",
        category="correctness",
        passed=has_screenshot,
        description=(
            f"{f.name}: captures screenshots" if has_screenshot
            else f"{f.name}: missing screenshot capture"
        ),
    ))

    # ── 6. CDP / WebSocket harness ────────────────────────────────────────
    has_cdp = any(pat in content for pat in [
        "CDP", "cdp", "WebSocket", "chrome", "puppeteer", "DevTools",
        "cdp-harness", "createHarness",
    ])
    checks.append(TestCheck(
        name=f"{name}:cdp_harness",
        category="correctness",
        passed=has_cdp,
        description=(
            f"{f.name}: uses CDP harness for browser control" if has_cdp
            else f"{f.name}: no CDP/browser harness detected"
        ),
    ))

    # ── 7. Voice command support ──────────────────────────────────────────
    has_voice = any(pat in content for pat in [
        "voice", "is_voice", "VOICE", "voice_target", "voice_commands",
    ])
    checks.append(TestCheck(
        name=f"{name}:voice_support",
        category="correctness",
        passed=has_voice,
        description=(
            f"{f.name}: includes voice command support" if has_voice
            else f"{f.name}: missing voice command support"
        ),
    ))

    # ── 8. Target command counts (200 text + 50 voice) ────────────────────
    has_text_target = "200" in content
    has_voice_target = "50" in content
    has_targets = has_text_target and has_voice_target
    checks.append(TestCheck(
        name=f"{name}:command_targets",
        category="correctness",
        passed=has_targets,
        description=(
            f"{f.name}: declares 200 text + 50 voice command targets" if has_targets
            else f"{f.name}: missing target counts (need 200 text, 50 voice)"
        ),
    ))

    # ── 9. Error handling ─────────────────────────────────────────────────
    has_try_catch = "try {" in content or "try{" in content or ".catch(" in content
    checks.append(TestCheck(
        name=f"{name}:error_handling",
        category="correctness",
        passed=has_try_catch,
        description=(
            f"{f.name}: has try/catch error handling" if has_try_catch
            else f"{f.name}: missing error handling (try/catch)"
        ),
    ))

    # ── 10. 'Did you mean' clarify check ─────────────────────────────────
    has_clarify = "Did you mean" in content or "clarify" in content.lower()
    checks.append(TestCheck(
        name=f"{name}:clarify_detection",
        category="correctness",
        passed=has_clarify,
        description=(
            f"{f.name}: checks for 'Did you mean' clarify trigger" if has_clarify
            else f"{f.name}: missing clarify_triggered check"
        ),
    ))

    return checks
